with latest as (select * from (select *, row_number() over (partition by method order by amount desc nulls first, id) as row_num from payments) ranked where row_num = 1) select s.id, s.order_id, s.method, s.status, s.row_num, case when method rlike '^(card|bank_transfer)$' then 'GROUP_B' else 'GROUP_A' end as method_zone, (select min(x.cost) from shipments x where x.order_id = s.order_id) as min_shipment_cost from latest s order by status desc;
